def reset_bts_configuration(
    remove_operator_certificates=False,
    remove_user_account_credentials=False,
    repair_center_reset=False,
    timeout=500,
    connection=None,
    detailed_output=False,
    reset_type=None,
    fdsw_ip="192.168.255.129",
    fdsw_username="Nemuadmin",
    fdsw_password="nemuuser",
    fdsw_port=443,
    wait_for_admin_connection=True,
    wait_for_admin_connection_timeout=600,
    remote_host=None,
    remote_host_username="ute",
    remote_host_password="ute",
    secondary_remote_host=None,
    secondary_remote_host_username="ute",
    secondary_remote_host_password="ute",
    remove_wifi_configuration=False,
    fdsw_log_level="INFO",
    fdsw_log_dir_path="/home/ute/",
    reset_admin_connection=False,
):
    """
    Reset configuration adapter - automatically check which method for reset configuration should be used and run it.

    :param boolean remove_operator_certificates: Remove operator certificates
    :param boolean remove_user_account_credentials: Remove user account credentials
    :param boolean repair_center_reset: Remove all from both partitions
    :param boolean remove_wifi_configuration: Remove WiFi configuration too (WithWifi option)
    :param bool detailed_output: return full request response when True, defaults set to False.
    :param int timeout: Timeout for the reset_configuration operation
    :param str fdsw_ip: Mplane or LMP ip address
    :param str fdsw_username: FDSW API username
    :param str fdsw_password: FDSW API password
    :param boolean wait_for_admin_connection: Wait for admin connection after configuration reset
    :param int wait_for_admin_connection_timeout: timeout for admin connection after configuration reset
    :param Union[AdminConnection,str] connection: AdminConnection object or if used, string name alias.
    :param string remote_host: remote host ip address for SSH tunneling. None means disabled SSH tunneling.
                                Do not use when BTS is connected to local machine!
    :param string remote_host_username: Username for remote host SSH authentication. Default is 'ute'.
    :param string remote_host_password: Password for remote host SSH authentication. Default is 'ute'.
    :param string secondary_remote_host: remote host ip address for SSH tunneling for Secondary SMOD.
                                         None means disabled SSH tunneling.
    :param string secondary_remote_host_username: Username for secondary remote host SSH authentication. Default is 'ute'.
    :param string secondary_remote_host_password: Password for secondary remote host SSH authentication. Default is 'ute'.
    :param str fdsw_log_level: Log level for FDSW connection. Default is 'INFO'.
    :param str fdsw_log_dir_path: Dir path for FDSW connection log.
    :param boolean reset_admin_connection: If True, reset admin connection after
                                           configuration reset(before wait_for_admin_connection).
    :return: None
    """
    coam_admin = admin()
    active_sw_version = coam_admin.get_sw_version(timeout=300, connection=connection)
    logging.info(f"Detected Software Version: {active_sw_version}")
    asw = SwVersionFactory.create_sw_version(active_sw_version)

    # Determine if new reset procedure should be used
    if not RawSwValidator.fsm3(active_sw_version) and (
        (
            asw.is_trunk_build()
            and asw >= SbtsSwVersion("SBTS23R4_ENB_9999_230601_000007")
        )
        or (
            not asw.is_trunk_build()
            and asw >= SbtsSwVersion("SBTS23R3_ENB_0000_000080_000000")
        )
    ):

        logging.debug(
            "Build is >= [SBTS23R4_ENB_9999_230601_000007, SBTS23R3_ENB_0000_000080_000000] - "
            "Use new configuration reset procedure (via Rescue Console)"
        )

        operation_kwargs = {
            "reset_params": {
                "remove_operator_certificates": remove_operator_certificates,
                "remove_user_account_credentials": remove_user_account_credentials,
                "repair_center_reset": repair_center_reset,
                "remove_wifi_configuration": remove_wifi_configuration,
            }
        }
        operation_function = _fdsw_software_rollback
        logging.info("Performing software rollback...")

        _reset_configuration_and_perform_rc_operation(
            operation_function=operation_function,
            operation_kwargs=operation_kwargs,
            timeout=timeout,
            admin_connection=connection,
            wait_for_admin_connection=wait_for_admin_connection,
            wait_for_admin_connection_timeout=wait_for_admin_connection_timeout,
            reset_admin_connection=reset_admin_connection,
            detailed_output=detailed_output,
            fdsw_ip=fdsw_ip,
            fdsw_username=fdsw_username,
            fdsw_password=fdsw_password,
            fdsw_port=fdsw_port,
            remote_host=remote_host,
            remote_host_username=remote_host_username,
            remote_host_password=remote_host_password,
            secondary_remote_host=secondary_remote_host,
            secondary_remote_host_username=secondary_remote_host_username,
            secondary_remote_host_password=secondary_remote_host_password,
            fdsw_log_level=fdsw_log_level,
            fdsw_log_dir_path=fdsw_log_dir_path,
        )
    else:
        logging.debug("Use legacy configuration reset procedure")
        coam_admin.reset_configuration(
            remove_operator_certificates=remove_operator_certificates,
            remove_user_account_credentials=remove_user_account_credentials,
            timeout=timeout,
            detailed_output=detailed_output,
            reset_type=reset_type,
            connection=connection,
        )


def reset_configuration_with_software_upgrade(
    software_path,
    timeout=1200,
    connection=None,
    detailed_output=False,
    fdsw_ip="192.168.255.129",
    fdsw_port=443,
    fdsw_username="Nemuadmin",
    fdsw_password="nemuuser",
    wait_for_admin_connection=True,
    wait_for_admin_connection_timeout=600,
    reset_admin_connection=False,
    remote_host=None,
    remote_host_username="ute",
    remote_host_password="ute",
    secondary_remote_host=None,
    secondary_remote_host_username="ute",
    secondary_remote_host_password="ute",
    fdsw_log_level="INFO",
    fdsw_log_dir_path="/home/ute/",
):
    """
    Reset configuration with software upgrade via Rescue Console.
    Steps:
        1. Run reset configuration from ADMIN CLI with reset_type="ConfigurationWithDiagnosticAndRecoverySw"
        2. BTS is booted to FDSW partition
        3. Connect to FDSW and perform software update
        4. BTS is booted to target software with new software version

    :param int timeout: Timeout for the operation
    :param Union[AdminConnection,str] admin_connection: AdminConnection object or if used, string name alias.
    :param bool detailed_output: return full request response when True, defaults set to False.
    :param str fdsw_ip: Mplane or LMP ip address
    :param str fdsw_username: FDSW API username
    :param str fdsw_password: FDSW API password
    :param str fdsw_port: FDSW API port
    :param string remote_host: remote host ip address for SSH tunneling. None means disabled SSH tunneling.
                                Do not use when BTS is connected to local machine!
    :param string remote_host_username: Username for remote host SSH authentication. Default is 'ute'.
    :param string remote_host_password: Password for remote host SSH authentication. Default is 'ute'.
    :param string secondary_remote_host: remote host ip address for SSH tunneling for Secondary SMOD.
                                         None means disabled SSH tunneling.
    :param string secondary_remote_host_username: Username for remote host SSH authentication. Default is 'ute'.
    :param string secondary_remote_host_password: Password for remote host SSH authentication. Default is 'ute'.
    :param str fdsw_log_level: Log level for FDSW connection. Default is 'INFO'.
    :param str fdsw_log_dir_path: Dir path for FDSW connection log.
    :param str software_path: Path to the software package file for upgrade. This parameter is required.
    :return: None
    """
    operation_kwargs = {"software_path": software_path}
    operation_function = _fdsw_software_update
    logging.info("Performing software upgrade...")
    _reset_configuration_and_perform_rc_operation(
        operation_function=operation_function,
        operation_kwargs=operation_kwargs,
        timeout=timeout,
        admin_connection=connection,
        wait_for_admin_connection=wait_for_admin_connection,
        wait_for_admin_connection_timeout=wait_for_admin_connection_timeout,
        reset_admin_connection=reset_admin_connection,
        detailed_output=detailed_output,
        fdsw_ip=fdsw_ip,
        fdsw_username=fdsw_username,
        fdsw_password=fdsw_password,
        fdsw_port=fdsw_port,
        remote_host=remote_host,
        remote_host_username=remote_host_username,
        remote_host_password=remote_host_password,
        secondary_remote_host=secondary_remote_host,
        secondary_remote_host_username=secondary_remote_host_username,
        secondary_remote_host_password=secondary_remote_host_password,
        fdsw_log_level=fdsw_log_level,
        fdsw_log_dir_path=fdsw_log_dir_path,
    )


def _reset_configuration_and_perform_rc_operation(
    operation_function,
    operation_kwargs,
    timeout,
    admin_connection,
    detailed_output,
    fdsw_ip,
    fdsw_username,
    fdsw_password,
    fdsw_port,
    remote_host,
    remote_host_username,
    remote_host_password,
    secondary_remote_host,
    secondary_remote_host_username,
    secondary_remote_host_password,
    fdsw_log_level,
    fdsw_log_dir_path,
    wait_for_admin_connection,
    wait_for_admin_connection_timeout,
    reset_admin_connection,
):
    """
    Reset configuration and perform a specified operation (rollback or software update).

    :param callable operation_function: The function to perform the operation (_fdsw_software_update or _fdsw_software_rollback).
    :param dict operation_kwargs: Keyword arguments for the operation function.
    :param int timeout: Timeout for the operation.
    :param str admin_connection: AdminConnection object or IP address.
    :param str fdsw_username: FDSW API username.
    :param str fdsw_password: FDSW API password.
    :param int fdsw_port: FDSW API port.
    :param str remote_host: Remote host IP address for SSH tunneling. None means disabled SSH tunneling.
    :param str remote_host_username: Username for remote host SSH authentication.
    :param str remote_host_password: Password for remote host SSH authentication.
    :param str secondary_remote_host: Secondary remote host IP address for SSH tunneling.
    :param str secondary_remote_host_username: Username for secondary remote host SSH authentication.
    :param str secondary_remote_host_password: Password for secondary remote host SSH authentication.
    :param str fdsw_log_level: Log level for FDSW connection.
    :param str fdsw_log_dir_path: Directory path for FDSW connection logs.
    :return: None
    """
    coam_admin = admin()
    fdsw_rc = rc()
    remote_connections = []
    all_fdsw_params = _setup_fdsw_connections(
        admin_connection,
        remote_host,
        remote_host_username,
        remote_host_password,
        secondary_remote_host,
        secondary_remote_host_username,
        secondary_remote_host_password,
    )

    try:
        admin().reset_configuration(
            reset_type="ConfigurationWithDiagnosticAndRecoverySw",
            connection=admin_connection,
            detailed_output=detailed_output,
            timeout=120,
        )

        for fdsw_params in all_fdsw_params:
            if fdsw_params["ssh_host"]:
                logging.info(
                    "Setup remote tunnel - SERVER: {}, PORT: {}".format(
                        fdsw_params["ssh_host"], fdsw_params["local_port"]
                    )
                )
                copy_of_fdsw_params = fdsw_params.copy()
                del copy_of_fdsw_params["fdsw_alias"]
                remote_connection = fdsw_rc.setup_remote(**copy_of_fdsw_params)
                remote_connections.append(remote_connection)

                fdsw_port = fdsw_params["local_port"]
                fdsw_ip = fdsw_params["local_host"]

            operation_function(
                fdsw_rc=fdsw_rc,
                fdsw_connection_alias=fdsw_params["fdsw_alias"],
                fdsw_ip=fdsw_ip,
                fdsw_username=fdsw_username,
                fdsw_password=fdsw_password,
                fdsw_port=fdsw_port,
                fdsw_log_level=fdsw_log_level,
                fdsw_log_dir_path=fdsw_log_dir_path,
                timeout=timeout,
                **operation_kwargs,
            )
            logging.info(
                f"Operation {operation_function.__name__} completed successfully."
            )

    except Exception as e:
        logging.error(f"An error occurred during the operation: {repr(e)}")
        raise

    finally:
        if remote_connections:
            for remote_connection in remote_connections:
                fdsw_rc.disconnect_remote(remote_connection)
                logging.info("Disconnected remote connection.")
        if reset_admin_connection:
            _wait_till_succeeds(
                coam_admin.reset_admin,
                interval=60,
                wait_timeout=wait_for_admin_connection_timeout,
                connection=admin_connection,
            )

        if wait_for_admin_connection:
            _wait_till_succeeds(
                coam_admin.get_bts_info,
                wait_timeout=wait_for_admin_connection_timeout,
                connection=admin_connection,
                timeout=600,
            )


def _setup_fdsw_connections(
    admin_connection,
    remote_host,
    remote_host_username,
    remote_host_password,
    secondary_remote_host,
    secondary_remote_host_username,
    secondary_remote_host_password,
):
    if remote_host is None:
        admin_c = (
            admin_connection
            if isinstance(admin_connection, AdminConnection)
            else admin.store.get(admin_connection)
        )
        remote_host = admin_c._api_client.process.remote_host
        remote_host_username = admin_c._api_client.process.ssh_username
        remote_host_password = admin_c._api_client.process.ssh_password

    local_host = "localhost"
    all_fdsw_params = [
        {
            "ssh_host": remote_host,
            "ssh_port": 22,
            "ssh_username": remote_host_username,
            "ssh_password": remote_host_password,
            "local_host": local_host,
            "local_port": 8561,
            "fdsw_alias": "FDSW_CONNECTION",
        }
    ]

    if _is_dual_core_configuration(connection=admin_connection):
        if secondary_remote_host:
            all_fdsw_params.append(
                {
                    "ssh_host": secondary_remote_host,
                    "ssh_port": 22,
                    "ssh_username": secondary_remote_host_username,
                    "ssh_password": secondary_remote_host_password,
                    "local_host": local_host,
                    "local_port": 8562,
                    "fdsw_alias": "FDSW_SECONDARY_CONNECTION",
                }
            )
            all_fdsw_params[0]["fdsw_alias"] = "FDSW_PRIMARY_CONNECTION"

    return all_fdsw_params


def _fdsw_software_update(
    software_path,
    fdsw_rc,
    fdsw_connection_alias,
    timeout,
    fdsw_ip,
    fdsw_username,
    fdsw_password,
    fdsw_port,
    fdsw_log_level,
    fdsw_log_dir_path,
):
    if software_path is None:
        raise ValueError(
            "The 'software_path' parameter cannot be None. Please provide a valid path to the software package."
        )
    _wait_for_rc_connection(
        fdsw_rc=fdsw_rc,
        fdsw_ip=fdsw_ip,
        fdsw_username=fdsw_username,
        fdsw_password=fdsw_password,
        fdsw_connection_alias=fdsw_connection_alias,
        timeout=timeout,
        interval=20,
        port=fdsw_port,
        fdsw_log_level=fdsw_log_level,
        fdsw_log_dir_path=fdsw_log_dir_path,
    )
    logging.debug(
        f"Perform Software Update with parameters: sw_pkg_path={software_path}"
    )
    fdsw_rc.software_update(
        sw_pkg_path=software_path,
        activate=True,
        connection=fdsw_connection_alias,
        timeout=timeout,
    )


def _fdsw_software_rollback(
    reset_params,
    fdsw_rc,
    fdsw_connection_alias,
    timeout,
    fdsw_ip,
    fdsw_username,
    fdsw_password,
    fdsw_port,
    fdsw_log_level,
    fdsw_log_dir_path,
):

    _wait_for_rc_connection(
        fdsw_rc=fdsw_rc,
        fdsw_ip=fdsw_ip,
        fdsw_username=fdsw_username,
        fdsw_password=fdsw_password,
        fdsw_connection_alias=fdsw_connection_alias,
        timeout=timeout,
        interval=20,
        port=fdsw_port,
        fdsw_log_level=fdsw_log_level,
        fdsw_log_dir_path=fdsw_log_dir_path,
    )

    software_inventory = fdsw_rc.get_all_software_inventory(
        connection=fdsw_connection_alias
    )
    logging.debug("SOFTWARE INVENTORY: {}".format(software_inventory))
    target_slot_id = fdsw_rc.get_active_sw_partition(connection=fdsw_connection_alias)
    config_reset_options = _get_supported_config_reset_options_for_proper_slot(
        software_inventory, target_slot_id
    )
    logging.debug(
        "SUPPORTED CONFIG RESET OPTIONS for SLOT_ID: {}  {}".format(
            target_slot_id, config_reset_options
        )
    )
    config_reset_type = _get_proper_config_reset_type(
        config_reset_options, **reset_params
    )

    logging.debug(
        "Perform Software Rollback with parameters: sw_slot_id={}, reset_type={}".format(
            target_slot_id, config_reset_type
        )
    )
    fdsw_rc.software_rollback(
        sw_slot_id=target_slot_id,
        reset_type=config_reset_type,
        connection=fdsw_connection_alias,
        timeout=120,
    )


def _is_dual_core_configuration(connection):
    bts_info = admin().get_bts_info(connection=connection, timeout=300)
    if len(bts_info["systemModules"]) == 2:
        return True
    return False


def _get_supported_config_reset_options_for_proper_slot(
    software_inventory, target_slot_id
):
    for slot_info in software_inventory["slots"]:
        if int(target_slot_id) == int(slot_info["id"]):
            return slot_info["supported_config_reset_options"]


def _get_proper_config_reset_type(
    config_reset_options,
    remove_operator_certificates,
    remove_user_account_credentials,
    repair_center_reset,
    remove_wifi_configuration,
):
    """# noqa: E501
    +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
    | GUI Options                                                                                                                   | Description                                      | reset_type value            |
    +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
    | Default                                                                                                                       | warm reset(no configuration removal)             |                             |
    +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
    | Delete BTS configuration from active partition                                                                                |                                                  | FromActive                  |
    +-------------------------------------------------------------------------------------------------------------------------------+                                                  +-----------------------------+
    | Delete BTS configuration with installed operator certificates from active partition                                           |                                                  | WithCertFromActive          |
    +-------------------------------------------------------------------------------------------------------------------------------+ configuration reset - only from active partition +-----------------------------+
    | Delete BTS configuration with credentials from active partition                                                               |                                                  | WithCredsFromActive         |
    +-------------------------------------------------------------------------------------------------------------------------------+                                                  +-----------------------------+
    | Delete BTS configuration with installed operator certificates and credentials from active partition                           |                                                  | WithCertsAndCredsFromActive |
    +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
    | Delete BTS configuration with all operator provided data including the security credentials from active and passive partition | repair center reset(both partitions)             | RepairCenterReset           |
    +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
    """

    if repair_center_reset:
        reset_type = "RepairCenterReset"
    elif remove_operator_certificates and remove_user_account_credentials:
        reset_type = "WithCertsAndCredsFromActive"
    elif remove_operator_certificates:
        reset_type = "WithCertFromActive"
    elif remove_user_account_credentials:
        reset_type = "WithCredsFromActive"
    else:
        reset_type = "FromActive"

    if isinstance(config_reset_options[0], (list, tuple)):
        reset_type = [reset_type]
        if remove_wifi_configuration and not repair_center_reset:
            reset_type.append("WithWifi")

    return reset_type


def _wait_for_rc_connection(
    fdsw_rc,
    fdsw_ip,
    fdsw_username,
    fdsw_password,
    fdsw_connection_alias,
    timeout=180,
    interval=20,
    port=443,
    fdsw_log_level="INFO",
    fdsw_log_dir_path="/home/ute/",
):
    start_time = time.time()
    logging.info(
        "Connect to Rescue Console: IP: {}, USERNAME: {}, PASSWORD: {}, PORT: {}, ALIAS: {}".format(
            fdsw_ip, fdsw_username, fdsw_password, port, fdsw_connection_alias
        )
    )
    while time.time() < start_time + timeout:
        try:
            fdsw_rc.connect_to(
                ip_address=fdsw_ip,
                username=fdsw_username,
                password=fdsw_password,
                port=port,
                secure=True,
                auto_discover=True,
                fdsw_version="fdsw23d",
                name=fdsw_connection_alias,
                log_level=fdsw_log_level,
                file_path=os.path.join(
                    fdsw_log_dir_path, f"{fdsw_connection_alias}-jsilib.log"
                ),
            )
            break
        except Exception as e:
            logging.debug("Cannot connect to Rescue Console {}".format(repr(e)))
            logging.debug("Waiting {} sec for next attempt".format(interval))
            time.sleep(interval)
    else:
        raise Exception("Timeout passed for connection to Rescue Console")
    time.sleep(5)


def _wait_till_succeeds(func, interval=20, wait_timeout=600, *args, **kwargs):
    start_time = time.monotonic()
    end_time = start_time + time_to_seconds(time=wait_timeout)
    interval = time_to_seconds(time=interval)
    while time.monotonic() < end_time:
        try:
            func(*args, **kwargs)
            return
        except Exception as e:
            logging.debug("Cannot connect to ADMIN CLI {}".format(repr(e)))
            logging.info(f"Waiting {interval} seconds for next attempt")
            time.sleep(interval)
    raise TimeoutError(
        f"Function {func.__name__} did not succeed within {wait_timeout} seconds"
    )
